using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using LWS.TruckBilliards.Editor;
using LWS.TruckHockey.Editor;
using System.Collections.Generic;
using TMPro;
namespace LWS.TruckSports.Editor {
public static class SportsPolishAuthoring {
 [Serializable]sealed class SceneFacts {public string scene;public CameraFacts[] cameras;public ColliderFacts[] colliders;public BodyFacts[] bodies;public SettingFacts[] settings;}
 [Serializable]sealed class CameraFacts {public string name;public Vector3 position,rotation;public bool orthographic;public float size;public string fit;}
 [Serializable]sealed class ColliderFacts {public string name,type,material;public Vector3 position,rotation,scale,size,center;public float radius,friction,bounce;public bool trigger,enabled;}
 [Serializable]sealed class BodyFacts {public string name;public Vector3 position,rotation;public float mass,drag,angularDrag;public int constraints,collision;public bool gravity,kinematic;}
 [Serializable]sealed class SettingFacts {public string type,field;public float value;}
 static string PathOf(Transform t){string name=t.name;while(t.parent!=null){t=t.parent;name=t.name+"/"+name;}return name;}
 public static void Baseline(){Audit("baseline");SportsBuilder.Build();}
 public static void UpgradeBuild(){UpgradeBowling();foreach(var scene in new[]{BilliardsBuilder.ScenePath,HockeyAuthoring.Scene,LWS.TruckAirHockey.Editor.AirHockeyAuthoring.Scene,LWS.TruckWallball.Editor.WallballAuthoring.Scene})UpgradeScene(scene);Audit("after");SportsBuilder.Build();}
 public static void UpgradeBowling(){var scene=EditorSceneManager.OpenScene(LWS.TruckBowling.Editor.BowlingAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<LWS.TruckBowling.BowlingMatch>();foreach(var lane in m.lanes){lane.rollingLimit=40;lane.settleLimit=8;lane.stoppedSeconds=4;}EditorSceneManager.SaveScene(scene);}
 static void Tag(TextMesh text,string marker){if(text==null)return;var tag=text.GetComponent<SportsArenaTag>();if(tag==null)tag=text.gameObject.AddComponent<SportsArenaTag>();tag.text=text;tag.marker=marker;text.text=marker;}
 static SportsArenaOverlay Overlay(GameObject root,Camera camera,Bounds surface){var overlay=root.GetComponent<SportsArenaOverlay>();if(overlay==null)overlay=root.AddComponent<SportsArenaOverlay>();overlay.arenaCamera=camera;overlay.surface=surface;return overlay;}
 static SportsArenaOverlay.Dock Dock(SportsArenaOverlay overlay,TMP_Text text,Vector2 point,float width,float height,int font,Vector2 offset=default){var found=overlay.transform.Find(text.name+" Arena Dock");var plate=found==null?SportsUIAuthoring.Rect(text.name+" Arena Dock",overlay.transform,new Vector2(800,height),Vector2.zero).GetComponent<RectTransform>():found.GetComponent<RectTransform>();var image=plate.GetComponent<UnityEngine.UI.Image>();if(image==null)image=plate.gameObject.AddComponent<UnityEngine.UI.Image>();image.color=new Color(.009f,.024f,.033f,.87f);image.raycastTarget=false;text.transform.SetParent(plate,false);var r=text.rectTransform;r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.pivot=new Vector2(.5f,.5f);r.offsetMin=new Vector2(10,3);r.offsetMax=new Vector2(-10,-3);text.enableAutoSizing=true;text.fontSizeMax=font;text.fontSizeMin=Mathf.Min(20,font);text.textWrappingMode=TextWrappingModes.NoWrap;text.overflowMode=TextOverflowModes.Ellipsis;text.raycastTarget=false;return new SportsArenaOverlay.Dock{target=r,plate=plate,relative=point,width=width,height=height,offset=offset};}
 public static void UpgradeScene(string path){var scene=EditorSceneManager.OpenScene(path);var camera=UnityEngine.Object.FindAnyObjectByType<Camera>();if(camera==null)throw new Exception("Arena camera missing "+path);var fit=camera.GetComponent<SportsCameraFit>();if(fit==null)fit=camera.gameObject.AddComponent<SportsCameraFit>();fit.cameraTarget=camera;fit.arenaFit=true;var docks=new List<SportsArenaOverlay.Dock>();
  foreach(var canvas in UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include)){var scaler=canvas.GetComponent<UnityEngine.UI.CanvasScaler>();if(scaler!=null)scaler.screenMatchMode=UnityEngine.UI.CanvasScaler.ScreenMatchMode.Expand;}
  if(path==BilliardsBuilder.ScenePath){var m=UnityEngine.Object.FindAnyObjectByType<LWS.TruckBilliards.BilliardsMatch>();camera.transform.position=new Vector3(12,36,0);camera.transform.LookAt(new Vector3(0,.25f,0));fit.arenaBounds=new Bounds(new Vector3(0,.3f,0),new Vector3(14.2f,1.7f,26.3f));fit.topInset=.065f;fit.bottomInset=.095f;var h=UnityEngine.Object.FindAnyObjectByType<LWS.TruckBilliards.BilliardsHUD>();var overlay=Overlay(h.gameObject,camera,new Bounds(new Vector3(0,.2f,0),new Vector3(13.8f,0,25.8f)));docks.Add(Dock(overlay,h.playerPanel,new Vector2(.24f,1.025f),.47f,56,23));docks.Add(Dock(overlay,h.aiPanel,new Vector2(.76f,1.025f),.47f,56,23));docks.Add(Dock(overlay,h.banner,new Vector2(.19f,-.018f),.36f,36,25));docks.Add(Dock(overlay,h.scoreboard,new Vector2(.5f,-.018f),.25f,36,22));docks.Add(Dock(overlay,h.speed,new Vector2(.81f,-.018f),.36f,36,21));docks.Add(Dock(overlay,h.notice,new Vector2(.5f,-.09f),.98f,32,22));overlay.docks=docks.ToArray();foreach(var truck in new[]{m.player,m.ai})foreach(var text in truck.GetComponentsInChildren<TextMesh>())Tag(text,(truck.side+1).ToString());if(Array.Exists(m.balls,b=>b.presentation==null))BilliardsBallVisualAuthoring.Upgrade(m);}
  else if(path==HockeyAuthoring.Scene){var m=UnityEngine.Object.FindAnyObjectByType<LWS.TruckHockey.HockeyMatch>();camera.transform.position=new Vector3(0,31,-9);camera.transform.LookAt(Vector3.zero);fit.arenaBounds=new Bounds(new Vector3(0,.6f,0),new Vector3(40,2.4f,19.4f));fit.topInset=.065f;fit.bottomInset=.095f;var overlay=Overlay(m.menus.hud,camera,new Bounds(new Vector3(0,.1f,0),new Vector3(36.2f,0,18.7f)));docks.Add(Dock(overlay,m.menus.scoreText,new Vector2(.43f,1.012f),.52f,42,34));docks.Add(Dock(overlay,m.menus.clockText,new Vector2(.80f,1.012f),.19f,42,30));docks.Add(Dock(overlay,m.menus.messageText,new Vector2(.5f,1.012f),.74f,30,23,new Vector2(0,40)));if(m.menus.orangeTeamText==null)m.menus.orangeTeamText=SportsUIAuthoring.Text("Orange roster",m.menus.hud.transform,"",new Vector2(500,72),Vector2.zero,22);docks.Add(Dock(overlay,m.menus.teamText,new Vector2(.24f,-.029f),.47f,92,22));docks.Add(Dock(overlay,m.menus.orangeTeamText,new Vector2(.76f,-.029f),.47f,92,22));m.menus.controlsText.gameObject.SetActive(false);overlay.docks=docks.ToArray();for(int i=0;i<6;i++)Tag(m.labels[i],(i<3?"B":"O")+(i%3+1));}
  else if(path==LWS.TruckAirHockey.Editor.AirHockeyAuthoring.Scene){var m=UnityEngine.Object.FindAnyObjectByType<LWS.TruckAirHockey.AirHockeyMatch>();camera.transform.position=new Vector3(0,26,-9);camera.transform.LookAt(Vector3.zero);fit.arenaBounds=new Bounds(new Vector3(0,.5f,0),new Vector3(28.4f,2.2f,13.1f));fit.topInset=.065f;fit.bottomInset=.05f;var overlay=Overlay(m.menus.hud,camera,new Bounds(new Vector3(0,.1f,0),new Vector3(26.3f,0,12.8f)));docks.Add(Dock(overlay,m.menus.scoreText,new Vector2(.5f,1.025f),.95f,42,32));docks.Add(Dock(overlay,m.menus.noticeText,new Vector2(.5f,1.025f),.94f,30,23,new Vector2(0,40)));docks.Add(Dock(overlay,m.menus.serveText,new Vector2(.5f,-.028f),.95f,36,23));var controls=m.menus.hud.transform.Find("Controls");if(controls!=null)controls.gameObject.SetActive(false);overlay.docks=docks.ToArray();}
  else{var m=UnityEngine.Object.FindAnyObjectByType<LWS.TruckWallball.WallballMatch>();fit.arenaBounds=new Bounds(new Vector3(0,4.5f,-10),new Vector3(18,10,22));fit.topInset=.045f;fit.bottomInset=.065f;var overlay=Overlay(m.menus.hud,camera,fit.arenaBounds);docks.Add(Dock(overlay,m.menus.scoreText,new Vector2(.5f,1.015f),.76f,40,32));docks.Add(Dock(overlay,m.menus.serveText,new Vector2(.5f,-.014f),.94f,64,23));docks.Add(Dock(overlay,m.menus.noticeText,new Vector2(.5f,1.015f),.94f,36,22,new Vector2(0,-38)));m.menus.controlsText.gameObject.SetActive(false);overlay.docks=docks.ToArray();var oldLabel=GameObject.Find("Valid wall label");if(oldLabel!=null)oldLabel.GetComponent<TextMesh>().characterSize=.13f;var p=UnityEngine.Object.FindAnyObjectByType<LWS.TruckWallball.WallballPresentation>();for(int i=0;i<2;i++){Tag(p.labels[i],(i+1).ToString());p.labels[i].GetComponent<Renderer>().enabled=false;}}
  fit.Apply();EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("TS_POLISH_ARENA_SAVED "+scene.name+" safeFit="+camera.orthographicSize);}
 public static void Audit(string tag){Directory.CreateDirectory("Logs/TruckSports/Polish");foreach(var path in new[]{SportsBuilder.FrontScene,BilliardsBuilder.ScenePath,HockeyAuthoring.Scene,LWS.TruckBowling.Editor.BowlingAuthoring.Scene,LWS.TruckAirHockey.Editor.AirHockeyAuthoring.Scene,LWS.TruckWallball.Editor.WallballAuthoring.Scene}){var scene=EditorSceneManager.OpenScene(path);var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var facts=new SceneFacts{scene=path,cameras=all.Select(t=>t.GetComponent<Camera>()).Where(c=>c!=null).Select(c=>new CameraFacts{name=PathOf(c.transform),position=c.transform.position,rotation=c.transform.eulerAngles,orthographic=c.orthographic,size=c.orthographicSize,fit=c.GetComponent<SportsCameraFit>()==null?"":JsonUtility.ToJson(c.GetComponent<SportsCameraFit>())}).ToArray(),colliders=all.SelectMany(t=>t.GetComponents<Collider>()).Select(c=>new ColliderFacts{name=PathOf(c.transform),type=c.GetType().Name,position=c.transform.position,rotation=c.transform.eulerAngles,scale=c.transform.lossyScale,size=c is BoxCollider b?b.size:Vector3.zero,center=c is BoxCollider box?box.center:c is SphereCollider s?s.center:Vector3.zero,radius=c is SphereCollider sphere?sphere.radius:0,material=c.sharedMaterial?.name,friction=c.sharedMaterial==null?0:c.sharedMaterial.dynamicFriction,bounce=c.sharedMaterial==null?0:c.sharedMaterial.bounciness,trigger=c.isTrigger,enabled=c.enabled}).OrderBy(c=>c.name).ToArray(),bodies=all.Select(t=>t.GetComponent<Rigidbody>()).Where(b=>b!=null).Select(b=>new BodyFacts{name=PathOf(b.transform),position=b.position,rotation=b.rotation.eulerAngles,mass=b.mass,drag=b.linearDamping,angularDrag=b.angularDamping,constraints=(int)b.constraints,collision=(int)b.collisionDetectionMode,gravity=b.useGravity,kinematic=b.isKinematic}).OrderBy(b=>b.name).ToArray(),settings=all.SelectMany(t=>t.GetComponents<MonoBehaviour>()).Where(m=>m!=null&&m.GetType().Namespace!=null&&m.GetType().Namespace.StartsWith("LWS.Truck")&&!m.GetType().Name.Contains("Menu")&&!m.GetType().Name.Contains("Camera")).SelectMany(m=>m.GetType().GetFields().Where(f=>f.FieldType==typeof(float)).Select(f=>new SettingFacts{type=m.GetType().Name,field=f.Name,value=(float)f.GetValue(m)})).OrderBy(s=>s.type+"/"+s.field).ToArray()};File.WriteAllText("Logs/TruckSports/Polish/"+tag+"-"+scene.name+".json",JsonUtility.ToJson(facts,true));Debug.Log("TS_POLISH_AUDIT "+scene.name+" bodies="+facts.bodies.Length+" colliders="+facts.colliders.Length);}}
}
}
